import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listarArquivos } from './solution.mjs';

function leitorDaArvore() {
  return {
    async readdir(caminho) {
      if (caminho === '.') {
        return [
          { nome: 'package.json', eDiretorio: false },
          { nome: 'src', eDiretorio: true },
        ];
      }
      if (caminho === './src') {
        return [
          { nome: 'app.mjs', eDiretorio: false },
          { nome: 'dados', eDiretorio: true },
        ];
      }
      if (caminho === './src/dados') {
        return [{ nome: 'lista.txt', eDiretorio: false }];
      }
      return [];
    },
  };
}

test('lista os arquivos das subpastas (recursão)', async () => {
  const resultado = await listarArquivos(leitorDaArvore(), '.');
  assert.deepEqual(resultado.slice().sort(), [
    './package.json',
    './src/app.mjs',
    './src/dados/lista.txt',
  ].sort());
});

test('pasta vazia devolve lista vazia', async () => {
  const leitor = { async readdir() { return []; } };
  assert.deepEqual(await listarArquivos(leitor, 'vazio'), []);
});

test('lança erro se o leitor não tiver readdir', async () => {
  await assert.rejects(() => listarArquivos({}, '.'), /readdir/);
});

test('deixa o erro do leitor subir (não engole)', async () => {
  const leitor = {
    async readdir(caminho) {
      throw new Error('disco quebrado: ' + caminho);
    },
  };
  await assert.rejects(() => listarArquivos(leitor, '.'), /disco quebrado/);
});

solutionCode:
export async function listarArquivos(leitor, diretorio) {
  if (!leitor || typeof leitor.readdir !== 'function') {
    throw new Error('leitor precisa ter uma função readdir');
  }

  const arquivos = [];

  async function percorrer(atual) {
    const itens = await leitor.readdir(atual);

    for (const item of itens) {
      const caminho = atual + '/' + item.nome;

      if (item.eDiretorio) {
        await percorrer(caminho); // é pasta: entra nela (recursão)
      } else {
        arquivos.push(caminho); // é arquivo: anota o caminho
      }
    }
  }

  await percorrer(diretorio);
  return arquivos;
}
